('opportunity:usaco','opportunity','{"id":"usaco","name":"USACO Online Contests","short":"{ }","org":"USA Computing Olympiad","cycle":"Next season · watchlist","type":"Olympiad","fields":["Computer science","Mathematics"],"formats":["Online"],"locations":["Online / worldwide"],"location":"Online · worldwide participation","eligibilityTags":["High school junior","Other high school","Pre-university gap year","University student"],"access":"International","eligibility":"Online contests and training are open to everyone. US team/camp selection is restricted to eligible pre-college students in the USA.","costGroup":"Free","aid":false,"cost":"Free","costNote":"The official rules state there is never a participation fee.","deadlineStart":null,"deadlineEnd":null,"deadline":"2026–27 schedule unannounced","deadlineDetail":"The checked homepage still lists 2025–26 dates. Those dates are not reused for the next season. Training remains available.","dateStatus":"Next cycle unannounced","status":"unannounced","schedule":"Next contest dates not verified as of 6 Nov 2026; archived training is available now.","description":"Algorithmic programming contests with Bronze, Silver, Gold and Platinum divisions and an extensive training archive.","output":"A contest score, division progress and demonstrable algorithmic skill.","effort":"Typically 4–5 continuous hours per contest","team":"Individual","caution":"Worldwide participation does not confer eligibility for the US national team. Future contest rules may change.","next":"Start Bronze-level training and watch the official season schedule.","sources":[["Official schedule","https://usaco.org/"],["Eligibility, fees & format","https://usaco.org/index.php?page=instructions"]],"deadlineConfirmed":false,"checkedOn":"2026-11-06","addedOn":"2026-11-06","finalDeadline":null,"archived":false}'::jsonb,'2026-11-06'::date,'active'),
('opportunity:kangaroo','opportunity','{"id":"kangaroo","name":"Math Kangaroo USA","short":"∑","org":"Math Kangaroo USA","cycle":"2027 competition","type":"Olympiad","fields":["Mathematics"],"formats":["In person"],"locations":["United States"],"location":"Participating US centers","eligibilityTags":["High school junior","Other high school"],"access":"Local requirements","eligibility":"Grades K–12. Center-specific location rules apply; do not assume an international or online entry route.","costGroup":"Paid","aid":true,"cost":"US$20 regular / US$35 late","costNote":"Regular enrollment through 31 Dec; late enrollment 1 Jan–1 Feb. Financial support may be available; ask the office.","deadlineStart":"2026-12-31","deadlineEnd":"2026-12-31","deadline":"31 Dec 2026 · regular","deadlineDetail":"Late enrollment closes 1 Feb 2027 at a higher fee. Universal cut-off timezone was not verified.","dateStatus":"Confirmed deadline","status":"confirmed","schedule":"Competition: 18 Mar 2027. Verify your selected center’s session details.","description":"An individual mathematical problem-solving competition for school students at participating centers.","output":"An individual problem-solving result and ranking in the relevant level.","effort":"Single competition session","team":"Individual","caution":"This record covers the USA organizer only. Other countries run separate Kangaroo competitions with different terms.","next":"Check the center eligibility and location before paying the registration fee.","sources":[["2027 dates & official fees","https://mathkangaroo.org/mks/resources/how-to-start-math-kangaroo-center/"],["USA organizer","https://mathkangaroo.org/mks/"]],"deadlineConfirmed":true,"checkedOn":"2026-11-06","addedOn":"2026-11-06","finalDeadline":"2027-02-01","archived":false}'::jsonb,'2026-11-06'::date,'active'),
('opportunity:bl4s','opportunity','{"id":"bl4s","name":"Beamline for Schools","short":"↗","org":"CERN · DESY · University of Bonn","cycle":"2027 competition","type":"Research challenge","fields":["Physics","Engineering"],"formats":["Online","In person"],"locations":["Online / worldwide","Europe"],"location":"Online proposal · winning teams travel to Europe","eligibilityTags":["High school junior","Other high school"],"access":"International","eligibility":"2027 terms specify secondary/high school students aged 16–19. FAQ wording is broader for younger/gap-year entrants; resolve exceptions with the organizer.","costGroup":"Free","aid":false,"cost":"Free · winners’ travel covered","costNote":"No entry fee. Travel, accommodation and meals are covered for invited winning teams.","deadlineStart":"2027-03-12","deadlineEnd":"2027-03-12","deadline":"12 Mar 2027","deadlineDetail":"23:59 CET (Geneva), equivalent to 13 Mar, 06:59 Hong Kong. Proposals open December 2026.","dateStatus":"Eligibility conflict","status":"caution","schedule":"Online information events from Nov 2026; winners conduct experiments in late Sep 2027.","description":"Design a particle-beam experiment and compete for the chance to carry it out at a major physics laboratory.","output":"A research proposal and experimental design; selected winners conduct the experiment.","effort":"Several months of proposal preparation","team":"At least 5 students + adult coach for lab-visit eligibility","caution":"Terms and FAQ differ on age and gap-year eligibility. Use the stricter 2027 terms until the organizer confirms an exception.","next":"Form a team, find a teacher coach and read the 2027 proposal guidance.","sources":[["2027 deadline & participation terms","https://beamlineforschools.cern/terms-and-conditions/"],["Team rules, fees & FAQ","https://beamlineforschools.cern/faqs/"],["2027 prizes & covered expenses","https://beamlineforschools.cern/prizes/"]],"deadlineConfirmed":true,"checkedOn":"2026-11-06","addedOn":"2026-11-06","finalDeadline":"2027-03-12","archived":false}'::jsonb,'2026-11-06'::date,'active'),
('opportunity:isef','opportunity','{"id":"isef","name":"Regeneron ISEF","short":"IS","org":"Society for Science","cycle":"2027 qualifying route","type":"Research challenge","fields":["Physics","Engineering","Biology","Computer science","Chemistry","Environment"],"formats":["In person"],"locations":["United States","Worldwide qualifying fairs"],"location":"Affiliated fairs worldwide → Los Angeles, US","eligibilityTags":["High school junior","Other high school"],"access":"Qualifying route","eligibility":"Grades 9–12 or equivalent; qualification through a Society-affiliated science fair is required. No direct individual entry to ISEF.","costGroup":"Unknown","aid":false,"cost":"Varies by fair & travel","costNote":"No single total cost applies to the qualifying route. Ask the affiliated fair about fees, funding and finalist travel.","deadlineStart":null,"deadlineEnd":null,"deadline":"Local qualifying fair deadline","deadlineDetail":"Your fair sets the entry deadline. Final affiliated fairs must be held by 12 Apr 2027; that is NOT a student application deadline.","dateStatus":"Local deadline varies","status":"partial","schedule":"May 2027, Los Angeles. Official pages show May 8–14 and May 9–14; verify your finalist itinerary.","description":"A global research competition reached through affiliated fairs, with independent student projects across science and engineering.","output":"An original research project, documented methods and a judged scientific presentation.","effort":"Months of research; approvals may be needed before experiments","team":"Individual or eligible team project; see current rules","caution":"Locate your affiliated fair first. Some research needs prior approvals; confirm rules before starting experiments.","next":"Find the fair serving your school or location and read its 2027 rules.","sources":[["Eligibility & qualification route","https://www.societyforscience.org/isef/faq/"],["2027 fair calendar","https://www.societyforscience.org/isef/affiliated-fa